  RiArrowDownSLine,
  RiComputerLine,
  RiSmartphoneLine,
  RiTabletLine,
} from "@remixicon/react";
import { AnimatePresence, motion } from "motion/react";
import { type ReactNode, useState } from "react";
import { Tab, TabList, TabPanel, Tabs } from "../../base/tabs/tabs";
import { IconButton } from "../../base/buttons/icon-button";
import { HorizontalScroll } from "../../base/scroll-area/horizontal-scroll";
import { CardSurface } from "./card-surface";
import { cx } from "@/lib/cx";
import { formatNumber } from "./chart-card";
import { BAR_LIST_DEMO_TABS } from "./chart-demo-data";
import { safeRatio, sum } from "./pro-chart";
export interface BarListItem {
  label: string;
  value: number;
  icon?: ReactNode;
  tone?: number;
  color?: string;
  href?: string;
}
export interface BarListTab {
  id: string;
  label: string;
  items: BarListItem[];
}
export interface BarListCardProps {
  data?: BarListItem[];
  items?: BarListItem[];
  tabs?: BarListTab[];
  title?: string;
  unit?: string;
  metricLabel?: string;
  metric?: "value" | "share";
  tone?: number;
  limit?: number;
  defaultTab?: string;
  onTabChange?: (id: string) => void;
  mono?: boolean;
  className?: string;
  height?: number | "auto";
}
export const BAR_LIST_DATA: BarListItem[] = [
  {
    label: "Desktop",
    value: 5980,
    icon: <RiComputerLine className="size-4" />,
  },
  {
    label: "Mobile",
    value: 3020,
    icon: <RiSmartphoneLine className="size-4" />,
  },
  { label: "Tablet", value: 820, icon: <RiTabletLine className="size-4" /> },
];
const TABS: BarListTab[] = BAR_LIST_DEMO_TABS.map((tab) => ({
  ...tab,
  items: tab.id === "devices" ? BAR_LIST_DATA : tab.items,
}));

function OverflowChevron({
  className,
  ...props
}: {
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}) {
  return (
    <RiArrowDownSLine
      {...props}
      className={cx(
        className,
        "size-3.5 text-text-secondary transition-transform duration-200 ease-out group-aria-expanded/bar-list-toggle:rotate-180",
      )}
    />
  );
}

function formatShare(value: number, total: number) {
  const percentage = safeRatio(value, total) * 100;
  return percentage > 0 && percentage < 0.5
    ? "<0.5%"
    : `${Math.round(percentage)}%`;
}

export function BarListCard({
  data,
  items,
  tabs: provided,
  title = "Pages",
  unit,
  metricLabel = "Visitors",
  metric = "share",
  tone = 6,
  limit = 5,
  defaultTab,
  onTabChange,
  mono = false,
  className,
  height = "auto",
}: BarListCardProps = {}) {
  const tabs = provided ?? (data || items ? undefined : TABS),
    [selected, setSelected] = useState(defaultTab ?? tabs?.[0]?.id),
    [expanded, setExpanded] = useState(false),
    [hover, setHover] = useState<string | null>(null);
  const rows = (tabItems: BarListItem[]) => {
    const sorted = [...tabItems].sort((a, b) => b.value - a.value),
      total = sum(sorted.map((r) => r.value)),
      maximum = Math.max(0, ...sorted.map((r) => r.value));
    return (
      <>
        <div className="relative -mx-2 -mb-1 flex flex-col">
          <ul
            className="flex flex-col gap-1"
            style={
              !expanded && sorted.length > limit
                ? {
                    maskImage:
                      "linear-gradient(black calc(100% - 44px), transparent)",
                  }
                : undefined
            }
          >
            {(expanded ? sorted : sorted.slice(0, Math.max(0, limit))).map(
              (row) => (
                <li
                  key={row.label}
                  onMouseEnter={() => setHover(row.label)}
                  onMouseLeave={() => setHover(null)}
                  className="relative flex h-9 items-center justify-between gap-3 rounded-lg px-2.5"
                >
                  <div
                    className="absolute inset-y-0 start-0 rounded-lg transition-[width,background-color] duration-500 ease-out"
                    style={{
                      width: `${safeRatio(row.value, maximum) * 100}%`,
                      backgroundColor: `color-mix(in srgb, ${mono ? "var(--color-text-tertiary)" : (row.color ?? `var(--color-chart-${row.tone ?? tone}${hover === row.label ? "-active" : ""})`)} ${hover === row.label ? 26 : 14}%, transparent)`,
                    }}
                  />
                  <span className="relative flex min-w-0 items-center gap-2 text-body-regular text-text-primary">
                    {row.icon && (
                      <span className="flex size-4 shrink-0 items-center justify-center text-text-secondary">
                        {row.icon}
                      </span>
                    )}
                    {row.href ? (
                      <a
                        href={row.href}
                        className="truncate outline-none hover:underline focus-visible:ring-2 focus-visible:ring-border-focus-ring"
                      >
                        {row.label}
                      </a>
                    ) : (
                      <span className="truncate">{row.label}</span>
                    )}
                  </span>
                  <span className="relative shrink-0 text-body-medium text-text-primary tabular-nums">
                    {metric === "value"
                      ? formatNumber(row.value)
                      : formatShare(row.value, total)}
                  </span>
                </li>
              ),
            )}
          </ul>
          <AnimatePresence initial={false}>
            {expanded && sorted.length > limit && (
              <motion.div
                className="overflow-hidden"
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: "auto", opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
              >
                <div className="flex flex-col gap-1 pt-1" />
              </motion.div>
            )}
          </AnimatePresence>
          {sorted.length > limit && (
            <IconButton
              icon={OverflowChevron}
              aria-expanded={expanded}
              variant="tertiary"
              size="compact"
              aria-label={
                expanded ? "Show fewer" : `Show ${sorted.length - limit} more`
              }
              onClick={() => setExpanded(!expanded)}
              className={cx(
                "group/bar-list-toggle absolute left-1/2 flex h-5 w-10 -translate-x-1/2 rounded-full border border-border-button-default bg-background-primary-default shadow-xs hover:bg-background-primary-hover",
                expanded ? "-bottom-2" : "bottom-1",
              )}
            />
          )}
        </div>
      </>
    );
  };
  const metricHeading = (
    <span className="shrink-0 pb-2.5 text-caption-1-medium tracking-[0.06em] text-text-tertiary uppercase">
      {unit ?? metricLabel}
    </span>
  );
  return (
    <CardSurface
      className={cx("flex w-full min-w-0 flex-col pt-1", className)}
      style={height === "auto" ? undefined : { height }}
    >
      {tabs ? (
        <Tabs
          selectedKey={selected}
          onSelectionChange={(key) => {
            setSelected(String(key));
            setExpanded(false);
            onTabChange?.(String(key));
          }}
          className="flex flex-col gap-3"
        >
          <div className="-mx-4 flex items-end gap-3 border-b border-separator-border px-4">
            <HorizontalScroll>
              <TabList
                scrollable={false}
                aria-label="Breakdown"
                bordered={false}
                className="w-max min-w-full"
              >
                {tabs.map((tab) => (
                  <Tab key={tab.id} id={tab.id}>
                    {tab.label}
                  </Tab>
                ))}
              </TabList>
            </HorizontalScroll>
            {metricHeading}
          </div>
          {tabs.map((tab) => (
            <TabPanel key={tab.id} id={tab.id} className="outline-none">
              {rows(tab.items)}
            </TabPanel>
          ))}
        </Tabs>
      ) : (
        <>
          <div className="-mx-4 mb-3 flex items-end justify-between border-b border-separator-border px-4">
            <p className="py-2 text-body-medium text-text-primary">{title}</p>
            {metricHeading}
          </div>
          {rows(items ?? data ?? [])}
        </>
      )}
    </CardSurface>
  );
}

