export function WeekSwitcher({
  label,
  onPrevious,
  onNext,
  compact = false,
  interactive = true,
  className,
}: {
  compact?: boolean;
  interactive?: boolean;
  className?: string;
  label: string;
  onPrevious: () => void;
  onNext: () => void;
}) {
  const [previousLabel, setPreviousLabel] = useState<string | null>(null);
  const [lastLabel, setLastLabel] = useState(label);
  const reduced = useHydratedReducedMotion();
  if (lastLabel !== label) {
    setPreviousLabel(lastLabel);
    setLastLabel(label);
  }
  if (compact)
    return (
      <div
        className={cx(
          "flex h-8 w-[151px] shrink-0 items-center justify-between gap-1 rounded-2lg border border-border-button-default bg-background-primary-default px-1 py-1 shadow-xs",
          className,
        )}
      >
        {interactive ? (
          <IconButton
            aria-label="Previous period"
            icon={ChevronLeft16}
            size="compact"
            variant="tertiary"
            className="size-4 rounded-[3px] bg-transparent text-text-secondary hover:bg-background-secondary-hover"
            onClick={onPrevious}
          />
        ) : (
          <span
            className="flex size-4 shrink-0 items-center justify-center text-text-secondary"
            aria-hidden
          >
            <ChevronLeft16 />
          </span>
        )}
        <span className="relative flex-1 overflow-hidden text-center text-body-medium whitespace-nowrap text-text-primary">
          <span className="invisible" aria-hidden>
            {label}
          </span>
          {previousLabel && !reduced && (
            <span
              key={`out-${label}`}
              aria-hidden
              className="animate-label-out absolute inset-0 flex items-center justify-center"
              onAnimationEnd={() => setPreviousLabel(null)}
            >
              {previousLabel}
            </span>
          )}
          <span
            key={label}
            className={cx(
              "absolute inset-0 flex items-center justify-center",
              previousLabel && !reduced && "animate-label-in",
            )}
          >
            {label}
          </span>
        </span>
        {interactive ? (
          <IconButton
            aria-label="Next period"
            icon={ChevronRight16}
            size="compact"
            variant="tertiary"
            className="size-4 rounded-[3px] bg-transparent text-text-secondary hover:bg-background-secondary-hover"
