"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { cx } from "@/lib/cx";
/** Horizontal content with an edge hint that follows its actual overflow. */
export function HorizontalScroll({
  children,
  className,
  edge = 28,
}: {
  children: ReactNode;
  className?: string;
  edge?: number;
}) {
  const ref = useRef<HTMLDivElement>(null),
    [fade, setFade] = useState({ left: false, right: true });
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => {
      const next = {
        left: element.scrollLeft > 1,
        right:
          element.scrollWidth - element.clientWidth - element.scrollLeft > 1,
      };
      setFade((old) =>
        old.left === next.left && old.right === next.right ? old : next,
      );
    };
    const resize = new ResizeObserver(measure),
      observed = new Set<Element>();
    const observe = () => {
      for (const node of [
        element,
        element.firstElementChild,
        element.firstElementChild?.firstElementChild,
      ])
        if (node && !observed.has(node)) {
          observed.add(node);
          resize.observe(node);
        }
      measure();
    };
    observe();
    const mutations = new MutationObserver(observe);
    mutations.observe(element, {
      subtree: true,
      childList: true,
      characterData: true,
    });
    element.addEventListener("scroll", measure, { passive: true });
    document.fonts?.addEventListener("loadingdone", measure);
    return () => {
      resize.disconnect();
      mutations.disconnect();
      element.removeEventListener("scroll", measure);
      document.fonts?.removeEventListener("loadingdone", measure);
    };
  }, []);
  const mask =
    fade.left && fade.right
      ? `linear-gradient(to right, transparent, black ${edge}px, black calc(100% - ${edge}px), transparent)`
      : fade.left
        ? `linear-gradient(to right, transparent, black ${edge}px, black)`
        : fade.right
          ? `linear-gradient(to right, black, black calc(100% - ${edge}px), transparent)`
          : undefined;
  return (
    <div
      ref={ref}
      className={cx(
        "min-w-0 flex-1 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
        className,
      )}
      style={{ maskImage: mask }}
    >
      {children}
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};
const clientSnapshot = () => true;
const serverSnapshot = () => false;

/** Keep the first server/client render identical, then apply the user's motion preference. */
export function useHydratedReducedMotion(): boolean {
  const reduced = useReducedMotion();
  const hydrated = useSyncExternalStore(subscribe, clientSnapshot, serverSnapshot);
  return hydrated && reduced === true;
}

